let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag("vagabond-app", "huntersmark"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "huntersmark")) return;

const state = hero.getFlag("vagabond-app", `ruleToggle_BScKQShDFq92Brhk`);

game.system.api.rules.toggleEffect(hero, "Compendium.vagabond-app.features.Item.BScKQShDFq92Brhk", state);

if (hero.getFlag("vagabond-app", "lethalprecision")) {
  game.system.api.rules.toggleEffect(hero, "Compendium.vagabond-app.features.Item.cszKHPwJzrURzUfG", state);
}

if (hero.getFlag("vagabond-app", "apexpredator")) {
  game.system.api.rules.toggleEffect(hero, "Compendium.vagabond-app.features.Item.oZzM52yqXRx3iqH5", state);
}
